int LoadGlApi(GlApi* api, void* (*getProc)(const char*, void*), void* user) {
  static_assert(sizeof(GlApi) == sizeof(void*) * kGlApiCount, "GlApi layout");
  void** slots = reinterpret_cast<void**>(api);
  int missing = 0;
  for (int i = 0; i < kGlApiCount; ++i) {
    slots[i] = getProc(kGlApiNames[i], user);
    if (!slots[i] && kGlApiIsCore[i]) ++missing;
  }
  return missing;
}

